package local.z6panel;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.database.Cursor;
import android.graphics.*;
import android.graphics.drawable.*;
import android.net.Uri;
import android.os.*;
import android.provider.MediaStore;
import android.util.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** MediaStore alternative for TV firmware without a working document picker. */
final class WallpaperAlbums {
 interface Host {void requestPermission();void receive();void importItems(List<WallpaperImports.Item> items);void back();}
 private final Activity activity;private final Host host;private final Handler ui=new Handler(Looper.getMainLooper());private final ThreadPoolExecutor worker=new ThreadPoolExecutor(1,1,10,TimeUnit.SECONDS,new ArrayBlockingQueue<>(10),r->new Thread(()->{android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);r.run();},"Z6-source-albums"));
 private final LruCache<String,Bitmap> cache=new LruCache<String,Bitmap>(4*1024*1024){protected int sizeOf(String k,Bitmap b){return b.getAllocationByteCount();}protected void entryRemoved(boolean evicted,String key,Bitmap old,Bitmap next){if(old!=next&&!old.isRecycled())old.recycle();}};
 private static final class Image {final String folder,name;final Uri uri;Image(String f,String n,Uri u){folder=f;name=n;uri=u;}}
 private final Map<String,WallpaperImports.Item> selected=new LinkedHashMap<>();private List<Image> images=Collections.emptyList();private final List<ImageView> views=new ArrayList<>();private String folder="";private int offset,epoch;private boolean visible;private LinearLayout list;private Button importButton;private TextView status;
 WallpaperAlbums(Activity a,Host h){activity=a;host=h;worker.allowCoreThreadTimeOut(true);}
 private int dp(int v){return Math.round(v*activity.getResources().getDisplayMetrics().density);}
 private TextView text(String s,int size){TextView t=new TextView(activity);t.setText(s);t.setTextSize(size);t.setTextColor(0xFFBBC3CC);return t;}
 private GradientDrawable bg(boolean focus){GradientDrawable d=new GradientDrawable();d.setColor(focus?0xFF354955:0xFF222E38);d.setCornerRadius(dp(5));if(focus)d.setStroke(dp(2),0xFFD2DFE5);return d;}
 private void style(View v){StateListDrawable d=new StateListDrawable();d.addState(new int[]{android.R.attr.state_focused},bg(true));d.addState(new int[]{},bg(false));v.setBackground(d);v.setFocusable(true);}
 private Button button(LinearLayout row,String label,Runnable run){Button b=new Button(activity);b.setText(label);b.setAllCaps(false);b.setTextSize(13);b.setTextColor(Color.WHITE);style(b);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(41),1);p.setMargins(dp(3),0,dp(3),0);row.addView(b,p);b.setOnClickListener(v->run.run());return b;}
 void show(){hide();visible=true;int token=epoch;list=new LinearLayout(activity);list.setOrientation(1);list.setBackgroundColor(0xFF121722);list.setPadding(dp(24),dp(12),dp(24),dp(12));TextView title=text("Desde TV o USB",22);title.setTextColor(Color.WHITE);list.addView(title);status=text("Cargando carpetas…",12);list.addView(status,new LinearLayout.LayoutParams(-1,dp(28)));LinearLayout tools=new LinearLayout(activity);list.addView(tools);button(tools,"Desde el celular",host::receive);importButton=button(tools,"Importar ("+selected.size()+")",()->{if(!selected.isEmpty())host.importItems(new ArrayList<>(selected.values()));});importButton.setEnabled(!selected.isEmpty());importButton.setAlpha(importButton.isEnabled()?1:.45f);activity.setContentView(list);
  if(activity.checkSelfPermission(Manifest.permission.READ_EXTERNAL_STORAGE)!=PackageManager.PERMISSION_GRANTED){status.setText("Permite consultar imágenes del TV o usa Desde el celular.");LinearLayout actions=new LinearLayout(activity);list.addView(actions);button(actions,"Permitir consultar imágenes",host::requestPermission);button(actions,"Volver",host::back);return;}
  worker.execute(()->{ArrayList<Image> found=new ArrayList<>();String error="";try{for(String volume:MediaStore.getExternalVolumeNames(activity)){Uri collection=MediaStore.Images.Media.getContentUri(volume);int count=0;try(Cursor cursor=activity.getContentResolver().query(collection,new String[]{MediaStore.Images.Media._ID,MediaStore.Images.Media.DISPLAY_NAME,MediaStore.Images.Media.RELATIVE_PATH},null,null,MediaStore.Images.Media.DISPLAY_NAME+" ASC")){while(cursor!=null&&cursor.moveToNext()&&count++<500){String path=cursor.getString(2);found.add(new Image((volume.equals(MediaStore.VOLUME_EXTERNAL_PRIMARY)?"TV":"Memoria externa")+" · "+(path==null?"Imágenes":path),cursor.getString(1),ContentUris.withAppendedId(collection,cursor.getLong(0))));}}}}catch(Exception e){error="Android no permite leer estas imágenes. Puedes enviarlas desde el celular.";}final String problem=error;ui.post(()->{if(!visible||token!=epoch)return;images=found;draw(token,problem);});});
 }
 private void draw(int token,String error){List<Object> choices=new ArrayList<>();if(folder.isEmpty()){Set<String> folders=new LinkedHashSet<>();for(Image i:images)folders.add(i.folder);choices.addAll(folders);}else for(Image i:images)if(i.folder.equals(folder))choices.add(i);offset=Math.min(offset,Math.max(0,(choices.size()-1)/8*8));status.setText(!error.isEmpty()?error:choices.isEmpty()?"No hay imágenes consultables. Copia fotos a Imágenes o envíalas desde el celular.":folder.isEmpty()?"Elige una carpeta · hasta 500 imágenes consultadas por volumen":"OK marca fotos · Importar las guarda en Z6");LinearLayout grid=new LinearLayout(activity);grid.setOrientation(1);LinearLayout.LayoutParams body=new LinearLayout.LayoutParams(-1,0,1);body.topMargin=dp(8);body.bottomMargin=dp(8);list.addView(grid,body);for(int r=0;r<2;r++){LinearLayout row=new LinearLayout(activity);grid.addView(row,new LinearLayout.LayoutParams(-1,0,1));for(int c=0;c<4;c++){int at=offset+r*4+c;LinearLayout card=new LinearLayout(activity);card.setOrientation(1);card.setGravity(Gravity.CENTER);card.setPadding(dp(6),dp(6),dp(6),dp(6));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,1);p.setMargins(dp(3),dp(3),dp(3),dp(3));row.addView(card,p);if(at>=choices.size())continue;Object choice=choices.get(at);style(card);card.setClickable(true);if(choice instanceof String){TextView label=text("▣\n"+choice,15);label.setGravity(Gravity.CENTER);card.addView(label);card.setOnClickListener(v->{folder=(String)choice;offset=0;show();});}else{Image item=(Image)choice;ImageView thumb=new ImageView(activity);thumb.setScaleType(ImageView.ScaleType.FIT_CENTER);card.addView(thumb,new LinearLayout.LayoutParams(-1,0,1));views.add(thumb);TextView label=text((selected.containsKey(item.uri.toString())?"✓ ":"")+item.name,12);label.setSingleLine(true);label.setEllipsize(android.text.TextUtils.TruncateAt.END);card.addView(label);card.setOnClickListener(v->{String key=item.uri.toString();if(selected.containsKey(key))selected.remove(key);else if(selected.size()<50)selected.put(key,new WallpaperImports.Item(item.uri,item.name));else{status.setText("Selecciona como máximo 50 imágenes");return;}label.setText((selected.containsKey(key)?"✓ ":"")+item.name);importButton.setText("Importar ("+selected.size()+")");importButton.setEnabled(!selected.isEmpty());importButton.setAlpha(importButton.isEnabled()?1:.45f);});Bitmap cached=cache.get(item.uri.toString());if(cached!=null)thumb.setImageBitmap(cached);else try{worker.execute(()->{Bitmap b=null;try{b=activity.getContentResolver().loadThumbnail(item.uri,new Size(320,180),null);}catch(Exception ignored){}final Bitmap result=b;ui.post(()->{if(result==null)return;if(!visible||token!=epoch){result.recycle();return;}cache.put(item.uri.toString(),result);thumb.setImageBitmap(result);});});}catch(RejectedExecutionException ignored){}}}}
  LinearLayout footer=new LinearLayout(activity);list.addView(footer);button(footer,"Anteriores",()->{if(offset>=8){offset-=8;show();}});TextView page=text((offset/8+1)+" / "+Math.max(1,(choices.size()+7)/8),12);page.setGravity(Gravity.CENTER);footer.addView(page,new LinearLayout.LayoutParams(0,dp(41),1));button(footer,"Siguientes",()->{if(offset+8<choices.size()){offset+=8;show();}});button(footer,"Volver",this::back);
 }
 void save(Bundle state){state.putString("source.folder",folder);state.putInt("source.offset",offset);ArrayList<String> uris=new ArrayList<>(),names=new ArrayList<>();for(WallpaperImports.Item item:selected.values()){uris.add(item.uri.toString());names.add(item.name);}state.putStringArrayList("source.uris",uris);state.putStringArrayList("source.names",names);}
 void restore(Bundle state){folder=state.getString("source.folder","");offset=state.getInt("source.offset",0);ArrayList<String> uris=state.getStringArrayList("source.uris"),names=state.getStringArrayList("source.names");if(uris!=null&&names!=null)for(int i=0;i<Math.min(50,Math.min(uris.size(),names.size()));i++)selected.put(uris.get(i),new WallpaperImports.Item(Uri.parse(uris.get(i)),names.get(i)));}
 void back(){if(!folder.isEmpty()){folder="";offset=0;show();}else host.back();}
 void hide(){visible=false;epoch++;worker.getQueue().clear();ui.removeCallbacksAndMessages(null);for(ImageView view:views)view.setImageDrawable(null);views.clear();cache.evictAll();}
 void destroy(){hide();worker.shutdownNow();}
 JSONObject inspect()throws JSONException{return new JSONObject().put("folder",folder).put("offset",offset).put("selectedCount",selected.size()).put("imageCount",images.size()).put("thumbnailBytes",cache.size()).put("permissionGranted",activity.checkSelfPermission(Manifest.permission.READ_EXTERNAL_STORAGE)==PackageManager.PERMISSION_GRANTED);}
 String action(String action){if(!visible)return "NOT_VISIBLE";if(action.startsWith("folder:")){folder=action.substring(7);offset=0;show();}else if(action.startsWith("mark_name:")){String name=action.substring(10);for(Image i:images)if(i.name.equals(name)){if(selected.containsKey(i.uri.toString()))selected.remove(i.uri.toString());else selected.put(i.uri.toString(),new WallpaperImports.Item(i.uri,i.name));return "OK";}return "NOT_FOUND";}else if(action.equals("import")){if(selected.isEmpty())return "EMPTY";host.importItems(new ArrayList<>(selected.values()));}else return "NOT_FOUND";return "OK";}
}
